// ---- end shared: common ----
const env = $env;
const data = $input.first().json;
const store = $getWorkflowStaticData('global');
store.seenAlerts = store.seenAlerts || {};
const seen = store.seenAlerts;
const now = Date.now();
const windowMs = envInt(env, 'DEDUP_WINDOW_MINUTES', 360, 1, 10080) * 60000;
const pendingMs = Math.min(windowMs, envInt(env, 'DEDUP_PENDING_MINUTES', 15, 1, 1440) * 60000);

const entryOf = (v) => {
  if (typeof v === 'number' && Number.isFinite(v)) return { state: 'confirmed', at: v };
  if (v && typeof v === 'object' && (v.state === 'pending' || v.state === 'confirmed') && Number.isFinite(v.at)) return v;
  return null;
};

for (const [k, v] of Object.entries(seen)) {
  const e = entryOf(v);
  if (!e || now - e.at > (e.state === 'pending' ? pendingMs : windowMs)) delete seen[k];
}

const fresh = [];
const duplicates = [];
for (const a of data.alerts) {
  const key = (a.fingerprint || (a.alert_name + '|' + a.service_name)) + '|' + a.started_at;
  const e = entryOf(seen[key]);
  if (e) {
    duplicates.push({ alert_name: a.alert_name, service_name: a.service_name, key, state: e.state === 'pending' ? 'in_progress' : 'processed' });
    continue;
  }
  seen[key] = { state: 'pending', at: now };
  fresh.push({ ...a, dedup_key: key });
}

return [{
  json: {
    ...data,
    alerts: fresh,
    duplicates,
    response: {
      accepted: true,
      new_alerts: fresh.length,
      duplicate_alerts: duplicates.length,
      resolved_alerts: data.resolved,
      rejected_alerts: data.rejected.length,
      rejected: data.rejected,
    },
  },
}];

// Workflow 01 – Node: "Create incident (backend) – BLOCKED".
// One item per new alert.
//
// BLOCKED: the backend has no machine endpoint that creates an incident from an
// alert. The approved contract (database/API_AND_INTEGRATION_CONTRACTS.md, B.3)
// lists only start/complete, investigations/:id/analysis, recovery-checks and
// incident-events, and none of them creates incidents. Until the backend adds
// one, this node does NOT invent a URL: it passes the alert on with
// incident_id = null and records why, so the investigation can still run and
// be tested. When the endpoint exists, replace this node with
// "Sign request" + "HTTP Request" (see workflow 07 for the pattern), and set
// incident_status to "created" or "failed" ("Confirm alert processing", N-3,
// releases failed alerts so a later delivery is processed again).

return $input.first().json.alerts.map((a) => ({
  json: {
    incident_id: null,
    investigation_id: null,
    incident_created: false,
    incident_status: 'blocked',
    incident_blocker: 'Backend endpoint for creating an incident from an alert does not exist yet (backend dependency BD-1).',
    alert_name: a.alert_name,
    service_name: a.service_name,
    severity: a.severity,
    started_at: a.started_at,
    summary: a.summary,
    dedup_key: a.dedup_key,
  },
}));

// Workflow 01 – Node: "Confirm alert processing" (N-3). Runs after the incident
// step, once per new alert (one item per alert, dedup_key set by "Detect
// duplicate alerts"):
//   incident_status "created" -> confirmed (duplicates are skipped for DEDUP_WINDOW_MINUTES)
//   incident_status "blocked" -> confirmed: BD-1 does not exist, nothing was
//                                attempted and the investigation still runs, so
//                                the occurrence is processed once (behaviour
//                                before N-3, unchanged)
//   anything else ("failed", missing) -> released: the key is removed, so the
//                                next delivery of this alert (Alertmanager repeat)
//                                is processed again.
// Items are passed on unchanged (plus dedup_state).

const store = $getWorkflowStaticData('global');
store.seenAlerts = store.seenAlerts || {};
const seen = store.seenAlerts;
const now = Date.now();
return $input.all().map((item) => {
  const j = item.json || {};
  let dedupState = 'none';
  if (typeof j.dedup_key === 'string' && j.dedup_key) {
    if (j.incident_status === 'created' || j.incident_status === 'blocked') {
      seen[j.dedup_key] = { state: 'confirmed', at: now };
      dedupState = 'confirmed';
    } else {
      delete seen[j.dedup_key];
      dedupState = 'released';
    }
  }
  return { json: { ...j, dedup_state: dedupState } };
});

// Workflow 01 – Node: "Intake result". Summarizes what happened to each alert
// (visible in the n8n execution log). soft_failure (N-2) is the one returned by
// workflow 05 (AI unavailable, analysis not stored); "Soft failure?" sends it to 09.
const alerts = $('Create incident (backend) – BLOCKED').all().map((i) => i.json);
return $input.all().map((item, idx) => {
  const rca = item.json || {};
  const a = alerts[idx] || {};
  return {
    json: {
      alert_name: a.alert_name,
      service_name: a.service_name,
      incident_id: a.incident_id,
      incident_created: a.incident_created,
      rca_status: rca.status || (rca.error ? 'workflow_error' : 'unknown'),
      rca_stored: rca.stored === true,
      error: rca.error || null,
      soft_failure: rca.soft_failure && typeof rca.soft_failure === 'object' ? rca.soft_failure : null,
    },
  };
});

